import{_ as a,c as i,a as t,aS as e}from"./chunks/framework.BB9D2qGO.js";const u=JSON.parse('{"title":"感动","description":"","frontmatter":{},"headers":[],"relativePath":"note/movie/感动.md","filePath":"note/movie/感动.md","lastUpdated":1755947889000}'),l={name:"note/movie/感动.md"},o=e('<h1 id="感动" tabindex="-1">感动 <a class="header-anchor" href="#感动" aria-label="Permalink to &quot;感动&quot;">​</a></h1><p>国内的电影其实也不乏感人的片子，直触灵魂的那种，我思来想去还是专门开一篇来介绍吧，因为它值得。</p><h2 id="八两金" tabindex="-1">八两金 <a class="header-anchor" href="#八两金" aria-label="Permalink to &quot;八两金&quot;">​</a></h2><ul><li>1989-12-21 中国香港 100分钟</li><li>类型：爱情 剧情 搞笑</li><li>导演：张婉婷</li><li>主演：洪金宝 张艾嘉 谢伟雄</li><li>介绍：张婉婷“移民三部曲”之一,时间背景为中国大陆改革开放初期。猴子(洪金宝)文革期间一声不吭离别家乡汕头台山偷渡赴美...</li></ul><p>这部剧是洪金宝唯一的一部文艺片，直击灵魂的佳作，有亲情，有爱情...</p><p><img src="https://img0.baidu.com/it/u=3836423504,2981214215&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=500&amp;h=666" alt=""></p><h2 id="海洋天堂" tabindex="-1">海洋天堂 <a class="header-anchor" href="#海洋天堂" aria-label="Permalink to &quot;海洋天堂&quot;">​</a></h2><ul><li>2010-06-18 中国大陆 106分钟</li><li>类型：剧情 文艺 家庭</li><li>导演：薛晓路</li><li>主演：李连杰 文章 桂纶镁 朱媛媛 董勇</li><li>百科：刚过21岁生日的大福(文章 饰)是个孤独症患者,父亲王心诚(李连杰 饰)在妻子去世后,一个人将大福养大,如今王心...</li></ul><p>这部剧是李连杰唯一的一部文艺片，谁说杰哥不会演文艺片的，演技爆炸。</p><p><img src="https://b0.bdstatic.com/1adfefb5c5cbd180ec64e833a389ffc0.jpg@h_1280" alt=""></p><h2 id="桃姐" tabindex="-1">桃姐 <a class="header-anchor" href="#桃姐" aria-label="Permalink to &quot;桃姐&quot;">​</a></h2><ul><li>2011-09-05 118分钟</li><li>类型：剧情 家庭 传记</li><li>导演：许鞍华</li><li>主演：叶德娴 刘德华 秦海璐 秦沛 黄秋生</li><li>百科：桃姐(叶德娴 饰)是侍候了李家数十年的老佣人,把第二代的少爷罗杰(刘德华 饰)抚养成人。讲述一位生长于大家庭的少爷罗杰与自幼照顾自己长大的家佣桃姐之间所发生的一段触动人心的“特殊母子情”的故事。</li></ul><p><img src="https://img1.baidu.com/it/u=3848326720,1451939505&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=800&amp;h=1142" alt=""></p>',13),p=[o];function r(c,m,s,n,d,h){return t(),i("div",null,p)}const f=a(l,[["render",r]]);export{u as __pageData,f as default};
